/* SPACETIME LAB — src/space/ephem.c: real Solar System catalog + calendar
 * time (include/stc/ephem.h).
 *
 * Own file. Includes: own header (stc/ephem.h, which pulls in stc/space.h),
 * core (stc/units.h for STC_G/STC_PI, stc/rng.h for the seeded belt-tracer
 * draw), and C stdlib (math.h, string.h, stddef.h). The compiled catalog
 * lives in src/space/ephem_data.c (GENERATED by tools/gen_ephem.py from
 * the raw files under data/horizons, see that file's header); this file
 * only ships the lookup/selection/time logic that consumes it.
 *
 * Claim classes (doc/SWE2-SYSTEM.md R2): catalog GM/radius/state vectors
 * are EXTERNAL (ephem_data.c). Calendar conversion and Kepler-element ->
 * Cartesian state are ANALYTIC (closed-form). Belt tracers are explicitly
 * ILLUSTRATIVE (a sampled population, not real asteroids) per ephem.h.
 */

#include "stc/ephem.h"

#include <math.h>
#include <stddef.h>
#include <stdio.h>
#include <string.h>

#include "stc/rng.h"
#include "stc/units.h"

/* --- generated catalog (src/space/ephem_data.c) ------------------------ */

#define STC_EPHD_NEPOCH 2
#define STC_EPHD_NSYS 9

extern const int stc_ephemd_n;
extern const StcEphemBody stc_ephemd_catalog[];
extern const double stc_ephemd_epoch_jd[STC_EPHD_NEPOCH];
extern const double stc_ephemd_state[][STC_EPHD_NEPOCH][6];
extern const int stc_ephemd_sys_catalog_index[STC_EPHD_NSYS];
extern const double stc_ephemd_sys_state[STC_EPHD_NSYS][STC_EPHD_NEPOCH][6];
extern const char *const stc_ephemd_source;

/* --- catalog lookup ------------------------------------------------------ */

int stc_ephem_count(void) { return stc_ephemd_n; }

const StcEphemBody *stc_ephem_get(int i) {
    if (i < 0 || i >= stc_ephemd_n) return NULL;
    return &stc_ephemd_catalog[i];
}

int stc_ephem_find(const char *name) {
    int i;
    if (!name) return -1;
    for (i = 0; i < stc_ephemd_n; i++) {
        if (strcmp(stc_ephemd_catalog[i].name, name) == 0) return i;
    }
    return -1;
}

int stc_ephem_epoch_count(void) { return STC_EPHD_NEPOCH; }

double stc_ephem_epoch_jd(int k) {
    if (k < 0 || k >= STC_EPHD_NEPOCH) return 0.0;
    return stc_ephemd_epoch_jd[k];
}

static int stc_ephem_sys_row(int i) {
    int s;
    for (s = 0; s < STC_EPHD_NSYS; s++) {
        if (stc_ephemd_sys_catalog_index[s] == i) return s;
    }
    return -1;
}

int stc_ephem_state(int i, int k, int use_system, double pos[3],
                    double vel[3]) {
    const double *v;
    if (i < 0 || i >= stc_ephemd_n || k < 0 || k >= STC_EPHD_NEPOCH ||
        !pos || !vel)
        return -1;
    if (use_system && stc_ephemd_catalog[i].system_id != 0) {
        int s = stc_ephem_sys_row(i);
        if (s < 0) return -1;
        v = stc_ephemd_sys_state[s][k];
    } else {
        v = stc_ephemd_state[i][k];
    }
    pos[0] = v[0]; pos[1] = v[1]; pos[2] = v[2];
    vel[0] = v[3]; vel[1] = v[4]; vel[2] = v[5];
    return 0;
}

const char *stc_ephem_source(void) { return stc_ephemd_source; }

/* --- time: TDB seconds since J2000.0 <-> JD TDB ------------------------- */

double stc_ephem_jd(double t) { return t / STC_DAY + STC_JD_J2000; }

double stc_ephem_t(double jd) { return (jd - STC_JD_J2000) * STC_DAY; }

/* Proleptic Gregorian calendar <-> Julian Day, after Meeus, "Astronomical
 * Algorithms" 2nd ed., ch. 7. "Proleptic" means the Gregorian leap-year
 * rule (divisible by 4, not by 100 unless by 400) is applied at every
 * date, including before the 1582 reform and for negative (BC) years, in
 * astronomical year numbering (year 0 = 1 BC, year -1 = 2 BC, ...). This
 * is deliberately NOT the mixed Julian/Gregorian calendar Horizons prints
 * in its own text banners; see ephem_check.c for the JD 38.0 sanity point
 * that tells the two apart at -4712-01-01 12:00. */

static double stc_ephem_floordiv(double a, double b) {
    return floor(a / b);
}

void stc_ephem_cal(double jd, int *year, int *month, int *day, int *hour,
                   int *minute, double *second) {
    double jdp, z, f, alpha, A, B, C, D, E;
    double dayf;
    int mm, yy, dd;
    double frac_day, secs;

    if (!year || !month || !day || !hour || !minute || !second) return;

    /* No extra pre-rounding here: jd already carries all the precision a
     * double can hold at its magnitude (about 2^(e-52) days, e = jd's
     * binary exponent -- roughly 8e-5 s at JD ~4.4e6, i.e. year +-5000).
     * Multiplying jd by a large day->microsecond factor before rounding
     * would only add another rounding step at the SAME magnitude and buys
     * nothing; see ephem_check.c calendar_roundtrip for the measured
     * bound this implies. */
    jdp = jd + 0.5;
    z = floor(jdp);
    f = jdp - z;

    alpha = stc_ephem_floordiv(z - 1867216.25, 36524.25);
    A = z + 1.0 + alpha - floor(alpha / 4.0); /* always the Gregorian
                                                 correction: proleptic */
    B = A + 1524.0;
    C = stc_ephem_floordiv(B - 122.1, 365.25);
    D = floor(365.25 * C);
    E = stc_ephem_floordiv(B - D, 30.6001);

    dayf = B - D - floor(30.6001 * E) + f;
    mm = (E < 14.0) ? (int)(E - 1.0) : (int)(E - 13.0);
    yy = (mm > 2) ? (int)(C - 4716.0) : (int)(C - 4715.0);

    dd = (int)floor(dayf);
    frac_day = dayf - (double)dd;
    secs = frac_day * 86400.0;
    /* clamp tiny FP overshoot at the day boundary */
    if (secs < 0.0) secs = 0.0;
    if (secs >= 86400.0) secs = 86400.0 - 1e-9;

    *year = yy;
    *month = mm;
    *day = dd;
    *hour = (int)(secs / 3600.0);
    secs -= (*hour) * 3600.0;
    *minute = (int)(secs / 60.0);
    secs -= (*minute) * 60.0;
    *second = secs;
}

double stc_ephem_jd_from_cal(int year, int month, int day, int hour,
                             int minute, double second) {
    long m0, yshift, mm;
    double yy, A, B, D;

    /* Normalise month into 1..12, carrying whole years; day/hour/minute/
     * second are accepted as-is (out-of-range day, e.g. day=32 or day=0,
     * needs no folding: it is just a real offset added to the JD below,
     * so the result is exact regardless). */
    m0 = (long)month - 1;
    yshift = (long)stc_ephem_floordiv((double)m0, 12.0);
    mm = m0 - yshift * 12 + 1; /* 1..12 */
    yy = (double)year + (double)yshift;

    if (mm <= 2) {
        yy -= 1.0;
        mm += 12;
    }

    A = floor(yy / 100.0);
    B = 2.0 - A + floor(A / 4.0); /* proleptic: always applied */

    D = (double)day +
        (hour * 3600.0 + minute * 60.0 + second) / 86400.0;

    return floor(365.25 * (yy + 4716.0)) + floor(30.6001 * ((double)mm + 1.0)) +
           D + B - 1524.5;
}

char *stc_ephem_format(double t, char *buf, int n) {
    int year, month, day, hour, minute;
    double second;
    double ts;
    double dayn;
    long sod;

    if (!buf || n <= 0) return buf;
    /* Whole-second arithmetic: round t, split into day number and
     * second-of-day exactly (doubles hold integers to 2^53), then take
     * only Y-M-D from the calendar routine at that day's noon, so the
     * clock never shows ":60" or loses a carry to JD roundoff. */
    ts = floor(t + 0.5) + 43200.0;          /* s since 2000-01-01 00:00 */
    dayn = floor(ts / 86400.0);
    sod = (long)(ts - dayn * 86400.0);
    stc_ephem_cal(STC_JD_J2000 + dayn, &year, &month, &day, &hour, &minute,
                  &second);
    hour = (int)(sod / 3600);
    minute = (int)((sod / 60) % 60);

    if (year < 0) {
        snprintf(buf, (size_t)n, "-%04d-%02d-%02d %02d:%02d:%02ld TDB",
                 -year, month, day, hour, minute, sod % 60);
    } else {
        snprintf(buf, (size_t)n, "%04d-%02d-%02d %02d:%02d:%02ld TDB",
                 year, month, day, hour, minute, sod % 60);
    }
    return buf;
}

/* --- Kepler osculating elements -> heliocentric Cartesian state --------
 * ANALYTIC, standard classical-elements conversion (e.g. Vallado, "Fund.
 * of Astrodynamics and Applications", ch. 2). Used only for belt tracers
 * (ILLUSTRATIVE). Eccentric anomaly from mean anomaly via a fixed-count
 * Newton solve (R4: bounded iteration, no unguarded while). */

#define STC_EPHEM_KEPLER_ITERS 50

static void stc_ephem_elements_to_state(double gm, double a, double e,
                                        double inc, double node,
                                        double argp, double M,
                                        double pos[3], double vel[3]) {
    double E, dE, n, r, cosE, sinE, xp, yp, xdp, ydp;
    double cosO, sinO, cosw, sinw, cosi, sini;
    double Px, Py, Pz, Qx, Qy, Qz;
    int it;

    E = M; /* initial guess */
    for (it = 0; it < STC_EPHEM_KEPLER_ITERS; it++) {
        double f = E - e * sin(E) - M;
        double fp = 1.0 - e * cos(E);
        dE = f / fp;
        E -= dE;
    }

    cosE = cos(E);
    sinE = sin(E);
    r = a * (1.0 - e * cosE);
    n = sqrt(gm / (a * a * a));

    xp = a * (cosE - e);
    yp = a * sqrt(1.0 - e * e) * sinE;
    xdp = -a * n * sinE / (1.0 - e * cosE);
    ydp = a * n * sqrt(1.0 - e * e) * cosE / (1.0 - e * cosE);

    cosO = cos(node); sinO = sin(node);
    cosw = cos(argp); sinw = sin(argp);
    cosi = cos(inc); sini = sin(inc);

    Px = cosO * cosw - sinO * sinw * cosi;
    Py = sinO * cosw + cosO * sinw * cosi;
    Pz = sinw * sini;
    Qx = -cosO * sinw - sinO * cosw * cosi;
    Qy = -sinO * sinw + cosO * cosw * cosi;
    Qz = cosw * sini;

    pos[0] = xp * Px + yp * Qx;
    pos[1] = xp * Py + yp * Qy;
    pos[2] = xp * Pz + yp * Qz;
    vel[0] = xdp * Px + ydp * Qx;
    vel[1] = xdp * Py + ydp * Qy;
    vel[2] = xdp * Pz + ydp * Qz;
    (void)r;
}

/* --- load ---------------------------------------------------------------- */

int stc_ephem_load(StcSpace *s, int k, unsigned groups, int belt_tracers,
                   unsigned long long seed) {
    int i, added;
    int *sim_index; /* catalog index -> sim index, or -1 */
    int sim_index_buf[256];
    int sun_i, sun_sim;
    double sun_pos[3], sun_vel[3];

    if (!s || k < 0 || k >= STC_EPHD_NEPOCH || groups == 0 ||
        (groups & ~(unsigned)STC_EPH_ALL) != 0)
        return -1;
    if (stc_ephemd_n > (int)(sizeof(sim_index_buf) / sizeof(sim_index_buf[0])))
        return -1; /* generated catalog outgrew the static scratch buffer */
    sim_index = sim_index_buf;
    for (i = 0; i < stc_ephemd_n; i++) sim_index[i] = -1;

    stc_space_clear(s, stc_ephem_t(stc_ephem_epoch_jd(k)));

    /* pass 1: everything that is not a moon (CORE/DWARFS/ASTEROIDS) */
    for (i = 0; i < stc_ephemd_n; i++) {
        const StcEphemBody *b = &stc_ephemd_catalog[i];
        double pos[3], vel[3], gm, radius;
        int parent_sim, use_system, idx;

        if (b->group == STC_EPH_MOONS) continue;
        if ((groups & b->group) == 0) continue;

        use_system = (b->system_id != 0) && ((groups & STC_EPH_MOONS) == 0);
        if (stc_ephem_state(i, k, use_system, pos, vel) != 0) return -1;
        gm = use_system ? b->gm_system : b->gm;
        radius = b->radius;
        parent_sim = b->parent ? sim_index[stc_ephem_find(b->parent)] : -1;

        idx = stc_space_add(s, b->name, b->kind, parent_sim, gm, radius,
                            pos, vel);
        if (idx < 0) return -2;
        sim_index[i] = idx;

        /* Zonal gravity (EPHEM-2): only meaningful once the planet is a
         * standalone body separate from its moons (use_system false); with
         * moons off it is a system barycentre and stays a point mass, per
         * ephem.h. j2 == 0 means "not modelled" (asteroids, Sun, ...). */
        if (!use_system && b->j2 != 0.0) {
            (void)stc_space_set_oblateness(s, idx, b->j2, b->j4, b->rref,
                                           b->pole);
        }
    }

    /* pass 2: moons, gated on their parent having been added */
    if (groups & STC_EPH_MOONS) {
        for (i = 0; i < stc_ephemd_n; i++) {
            const StcEphemBody *b = &stc_ephemd_catalog[i];
            double pos[3], vel[3];
            int parent_cat, parent_sim, idx;

            if (b->group != STC_EPH_MOONS) continue;
            parent_cat = stc_ephem_find(b->parent);
            if (parent_cat < 0) continue;
            parent_sim = sim_index[parent_cat];
            if (parent_sim < 0) continue; /* parent's group wasn't requested */

            if (stc_ephem_state(i, k, 0, pos, vel) != 0) return -1;
            idx = stc_space_add(s, b->name, b->kind, parent_sim, b->gm,
                                b->radius, pos, vel);
            if (idx < 0) return -2;
            sim_index[i] = idx;
        }
    }

    added = stc_space_live_massive(s);

    /* Horizons SSB vectors should already be barycentric; recentre only if
     * the residual is non-negligible (documented in ephem_check.c). */
    {
        double p[3], pmag, sum_abs;
        int j;
        stc_space_momentum(s, p);
        pmag = sqrt(p[0] * p[0] + p[1] * p[1] + p[2] * p[2]);
        sum_abs = 0.0;
        for (j = 0; j < s->nm; j++) {
            if (!s->alive[j]) continue;
            double m = s->gm[j] / STC_G;
            double v = sqrt(s->vx[j] * s->vx[j] + s->vy[j] * s->vy[j] +
                            s->vz[j] * s->vz[j]);
            sum_abs += m * v;
        }
        if (sum_abs > 0.0 && pmag / sum_abs >= 1e-9) {
            stc_space_to_barycentre(s);
        }
    }

    /* belt tracers: ILLUSTRATIVE, heliocentric osculating elements drawn
     * from a seeded splitmix64-backed stream (stc/rng.h), converted about
     * the Sun's own GM, then shifted to barycentric using the Sun's
     * post-load state actually sitting in `s` (so a to_barycentre() call
     * above is honoured). */
    sun_i = stc_ephem_find("Sun");
    sun_sim = (sun_i >= 0) ? sim_index[sun_i] : -1;
    if (belt_tracers > 0 && sun_sim >= 0) {
        StcRng64 rng;
        int t;
        sun_pos[0] = s->x[sun_sim]; sun_pos[1] = s->y[sun_sim];
        sun_pos[2] = s->z[sun_sim];
        sun_vel[0] = s->vx[sun_sim]; sun_vel[1] = s->vy[sun_sim];
        sun_vel[2] = s->vz[sun_sim];
        stc_rng64_seed(&rng, seed);
        for (t = 0; t < belt_tracers; t++) {
            double a = stc_rng64_uniform_range(&rng, 2.1 * STC_AU,
                                               3.3 * STC_AU);
            double e = stc_rng64_uniform_range(&rng, 0.0, 0.3);
            double inc = stc_rng64_uniform_range(&rng, 0.0,
                                                 20.0 * STC_PI / 180.0);
            double node = stc_rng64_uniform_range(&rng, 0.0, 2.0 * STC_PI);
            double argp = stc_rng64_uniform_range(&rng, 0.0, 2.0 * STC_PI);
            double M = stc_rng64_uniform_range(&rng, 0.0, 2.0 * STC_PI);
            double pos[3], vel[3];
            stc_ephem_elements_to_state(STC_GM_SUN, a, e, inc, node, argp, M,
                                        pos, vel);
            pos[0] += sun_pos[0]; pos[1] += sun_pos[1]; pos[2] += sun_pos[2];
            vel[0] += sun_vel[0]; vel[1] += sun_vel[1]; vel[2] += sun_vel[2];
            if (stc_space_add_tracer(s, pos, vel) < 0) return -2;
        }
    }

    return added;
}
